func newSettlementLine() unsafe.Pointer { return unsafe.Pointer(new(driversettlement.SettlementLine)) }

func newNSettlementLine(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]driversettlement.SettlementLine, n)))
}

func ptrSettlementLine(p unsafe.Pointer, c int32) any {
	r := (*driversettlement.SettlementLine)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.SettlementID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.LineNumber))
	case 5:
		return (*string)(unsafe.Pointer(&r.Category))
	case 6:
		return (*string)(unsafe.Pointer(&r.ComponentKind))
	case 7:
		return (*string)(unsafe.Pointer(&r.Method))
	case 8:
		return &r.Description
	case 9:
		return &r.Quantity
	case 10:
		return &r.Rate
	case 11:
		return &r.AmountMinor
	case 12:
		return (**string)(unsafe.Pointer(&r.ShipmentID))
	case 13:
		return (**string)(unsafe.Pointer(&r.MoveID))
	case 14:
		return (**string)(unsafe.Pointer(&r.PayEventID))
	case 15:
		return (**string)(unsafe.Pointer(&r.RecurringDeductionID))
	case 16:
		return (**string)(unsafe.Pointer(&r.RecurringEarningID))
	case 17:
		return (**string)(unsafe.Pointer(&r.PayCodeID))
	case 18:
		return (**string)(unsafe.Pointer(&r.AdvanceID))
	case 19:
		return (**string)(unsafe.Pointer(&r.EscrowAccountID))
	case 20:
		return &r.ProNumber
	case 21:
		return &r.AddedByAgent
	case 22:
		return &r.CreatedAt
	case 23:
		return &r.UpdatedAt
	}
	return nil
}

func valueSettlementLine(p unsafe.Pointer, c int32) any {
	r := (*driversettlement.SettlementLine)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.SettlementID)
	case 4:
		return int64(r.LineNumber)
	case 5:
		return string(r.Category)
	case 6:
		if r.ComponentKind == "" {
			return nil
		}
		return string(r.ComponentKind)
	case 7:
		if r.Method == "" {
			return nil
		}
		return string(r.Method)
	case 8:
		return r.Description
	case 9:
		return r.Quantity
	case 10:
		return r.Rate
	case 11:
		return r.AmountMinor
	case 12:
		if r.ShipmentID == nil {
			return nil
		}
		return string(*r.ShipmentID)
	case 13:
		if r.MoveID == nil {
			return nil
		}
		return string(*r.MoveID)
	case 14:
		if r.PayEventID == nil {
			return nil
		}
		return string(*r.PayEventID)
	case 15:
		if r.RecurringDeductionID == nil {
			return nil
		}
		return string(*r.RecurringDeductionID)
	case 16:
		if r.RecurringEarningID == nil {
			return nil
		}
		return string(*r.RecurringEarningID)
	case 17:
		if r.PayCodeID == nil {
			return nil
		}
		return string(*r.PayCodeID)
	case 18:
		if r.AdvanceID == nil {
			return nil
		}
		return string(*r.AdvanceID)
	case 19:
		if r.EscrowAccountID == nil {
			return nil
		}
		return string(*r.EscrowAccountID)
	case 20:
		if r.ProNumber == "" {
			return nil
		}
		return r.ProNumber
	case 21:
		return r.AddedByAgent
	case 22:
		return r.CreatedAt
	case 23:
		return r.UpdatedAt
	}
	return nil
}

func attachSettlementLine(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*driversettlement.SettlementLine)(p)
	switch rel {
	case 0:
		r.Settlement = (*driversettlement.Settlement)(child)
	case 1:
		r.Shipment = (*shipment.Shipment)(child)
	case 2:
		r.PayCode = (*paycode.PayCode)(child)
	}
}

func init() {
	disputesTable.Relations[0].Target = SettlementsSchema()
	disputesTable.Relations[1].Target = SettlementLinesSchema()
	disputesTable.Relations[2].Target = workerdb.WorkersSchema()
	disputesTable.Relations[3].Target = tenantdb.UsersSchema()
	payEventsTable.Relations[0].Target = workerdb.WorkersSchema()
	payEventsTable.Relations[1].Target = shipmentdb.ShipmentsSchema()
	payEventsTable.Relations[2].Target = SettlementsSchema()
	settlementsTable.Relations[0].Target = workerdb.WorkersSchema()
	settlementsTable.Relations[1].Target = SettlementBatchesSchema()
	settlementsTable.Relations[2].Target = driverpaydb.PayProfilesSchema()
	settlementsTable.Relations[3].Target = SettlementLinesSchema()
	settlementBatchesTable.Relations[0].Target = SettlementsSchema()
	settlementLinesTable.Relations[0].Target = SettlementsSchema()
	settlementLinesTable.Relations[1].Target = shipmentdb.ShipmentsSchema()
	settlementLinesTable.Relations[2].Target = paycodedb.PayCodesSchema()
}

